-- Dedicated fresh MySQL 8 database. All ordinary tables are InnoDB. NO PAD
-- utf8mb4_0900_bin preserves full case, code-point and trailing-space identity.
-- Application code under ledger_usage row lock owns every counter; no triggers.
CREATE TABLE IF NOT EXISTS messages(delivery_id VARCHAR(32) PRIMARY KEY,message_id VARCHAR(32) NOT NULL UNIQUE,op_id VARCHAR(128) NOT NULL UNIQUE,channel_id VARCHAR(26) NOT NULL,fingerprint VARCHAR(128) NOT NULL,payload_blob LONGBLOB NOT NULL,payload_bytes BIGINT NOT NULL,has_payload TINYINT GENERATED ALWAYS AS (payload_bytes>0) STORED,usage_payload_bytes BIGINT NOT NULL DEFAULT 0,accepted_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,dedupe_until BIGINT NOT NULL,status VARCHAR(32) NOT NULL,updated_at BIGINT NOT NULL,pending_targets BIGINT NOT NULL DEFAULT 0,provider_accepted_count BIGINT NOT NULL DEFAULT 0,provider_failed_count BIGINT NOT NULL DEFAULT 0,provider_target_count BIGINT NOT NULL DEFAULT 0,private_enqueued_count BIGINT NOT NULL DEFAULT 0,INDEX messages_retention(dedupe_until),INDEX messages_expiry(has_payload,expires_at,delivery_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS targets(delivery_id VARCHAR(32) NOT NULL,device_key VARCHAR(32) NOT NULL,pull_owner VARCHAR(32) NOT NULL,owner_generation BIGINT NOT NULL DEFAULT 0,control_epoch BIGINT NOT NULL DEFAULT 0,platform VARCHAR(16) NOT NULL,provider VARCHAR(16) NOT NULL,provider_token TEXT NOT NULL,route_generation BIGINT NOT NULL DEFAULT 0,accepted_at BIGINT NOT NULL DEFAULT 0,state VARCHAR(32) NOT NULL,next_attempt_at BIGINT NOT NULL,attempts BIGINT NOT NULL DEFAULT 0,attempt_id BIGINT NOT NULL DEFAULT 0,provider_status BIGINT,provider_error TEXT,receipt_at BIGINT,acked_at BIGINT,delivery_mode VARCHAR(16) NOT NULL DEFAULT 'provider',delivery_epoch BIGINT NOT NULL DEFAULT 0,private_claim VARCHAR(32),private_group VARCHAR(128),PRIMARY KEY(delivery_id,device_key),FOREIGN KEY(delivery_id) REFERENCES messages(delivery_id) ON DELETE CASCADE,INDEX targets_private_owner(pull_owner,delivery_mode,acked_at,private_claim,accepted_at,delivery_id,device_key),INDEX targets_private_logical(pull_owner,delivery_id,delivery_mode,acked_at,device_key),INDEX targets_private_group(private_group,private_claim),INDEX targets_private_recovery(private_claim,delivery_id,device_key),INDEX targets_due(provider,state,next_attempt_at,delivery_id,device_key),INDEX targets_device(pull_owner,accepted_at,delivery_id,acked_at),INDEX targets_owner_delivery(pull_owner,delivery_id,device_key,acked_at),INDEX targets_token_retirement(platform,provider_token(256),control_epoch)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS ledger_usage(singleton BIGINT PRIMARY KEY CHECK(singleton=1),messages BIGINT NOT NULL,targets BIGINT NOT NULL,bytes BIGINT NOT NULL,control_epoch BIGINT NOT NULL DEFAULT 0,private_pending BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS devices(device_key VARCHAR(32) PRIMARY KEY,platform VARCHAR(16) NOT NULL,provider VARCHAR(16),provider_token TEXT,route_generation BIGINT NOT NULL DEFAULT 0,route_revision BIGINT NOT NULL DEFAULT 1,retired_at BIGINT,coalesced_to VARCHAR(32),INDEX devices_retired(retired_at,device_key),INDEX devices_token(platform,provider_token(256))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS registration_aliases(old_key VARCHAR(32) PRIMARY KEY,new_key VARCHAR(32) NOT NULL,platform VARCHAR(16) NOT NULL,expires_at BIGINT NOT NULL,INDEX registration_alias_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS channels(channel_id VARCHAR(26) PRIMARY KEY,channel_name VARCHAR(128) NOT NULL,password_hash TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS channel_subscriptions(channel_id VARCHAR(26) NOT NULL,device_key VARCHAR(32) NOT NULL,PRIMARY KEY(channel_id,device_key),FOREIGN KEY(channel_id) REFERENCES channels(channel_id),FOREIGN KEY(device_key) REFERENCES devices(device_key),INDEX subscriptions_device(device_key,channel_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
-- A prefix is only an index filter, never token uniqueness or identity. The
-- single owner and ledger row lock serialize exact full-token UPDATE/INSERT.
CREATE TABLE IF NOT EXISTS retired_provider_tokens(marker_id BIGINT AUTO_INCREMENT PRIMARY KEY,platform VARCHAR(16) NOT NULL,provider_token TEXT NOT NULL,control_epoch BIGINT NOT NULL,INDEX retired_token(platform,provider_token(256),control_epoch)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS provider_cooldowns(provider VARCHAR(16) PRIMARY KEY,next_attempt_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
INSERT INTO ledger_usage(singleton,messages,targets,bytes) VALUES(1,0,0,0) ON DUPLICATE KEY UPDATE singleton=singleton;

CREATE TABLE IF NOT EXISTS private_usage(device_key VARCHAR(32) PRIMARY KEY,pending BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
